const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const pg = await b.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  const url = 'http://127.0.0.1:8095/#/pages/data/index';
  await pg.goto(url, { waitUntil: 'networkidle' });
  await pg.waitForTimeout(1500);
  await pg.screenshot({ path: 'data-shot.png' });
  // scroll chips to end
  const chips = await pg.$('.no-scrollbar');
  if (chips) { await pg.evaluate(el => el.scrollLeft = el.scrollWidth, chips); await pg.waitForTimeout(400); await pg.screenshot({ path: 'data-shot-chips.png' }); }
  await b.close();
  console.log('done');
})();

